use std::sync::Arc;

struct Stream { buf: Arc<Buffer> }
struct FileStream { buf: Arc<Buffer>, stream: Stream }

impl FileStream {
    fn new(fd: i32) -> Self {
        let buf = Arc::new(Buffer::for_fd(fd));   // payload first,
        let stream = Stream::new(Arc::clone(&buf)); // dependent part from it
        FileStream { buf, stream }
    }
}
